const data = $json.body || $json;

const name = String(data.name || "").trim();
const email = String(data.email || "").trim();

const experienceRaw =
  data.experience ??
  data.years ??
  data.yearsOfExperience ??
  "";

const experienceText = String(experienceRaw).trim();

const skills = Array.isArray(data.skills)
  ? data.skills.join(", ")
  : String(data.skills || "").trim();

const workExperience = String(
  data.workExperience ||
  data.experienceDetails ||
  ""
).trim();

const errors = [];

if (!name) {
  errors.push("Name is required.");
}

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (!emailRegex.test(email)) {
  errors.push("Please enter a valid email address.");
}

if (experienceText === "" || isNaN(Number(experienceText))) {
  errors.push("Years of experience must be a number.");
}

if (!skills) {
  errors.push("At least one skill is required.");
}

if (!workExperience) {
  errors.push("Work experience is required.");
}

if (errors.length > 0) {
  return [
    {
      json: {
        success: false,
        errors: errors
      }
    }
  ];
}

return [
  {
    json: {
      success: true,

      // BASIC DETAILS
      name: name,
      role: data.role || "",
      email: email,
      phone: data.phone || "",
      city: data.city || "",

      // EXPERIENCE
      experience: Number(experienceText),
      workExperience: workExperience,

      // SKILLS & EDUCATION
      skills: skills,
      education: data.education || "",

      // OBJECTIVE
      careerObjective:
        data.careerObjective ||
        data.summary ||
        "",

      // RESUME TYPE
      resumeType:
        data.resumeType ||
        "Professional Resume",

      // APPRENTICESHIP
      apprenticeship:
        data.apprenticeship ||
        "",

      apprenticeshipDuration:
        data.apprenticeshipDuration ||
        "",

      // PROJECTS
      projects:
        data.projects ||
        data.academicProjects ||
        "",

      // CERTIFICATIONS
      certifications:
        data.certifications ||
        "",

      // ACADEMIC DETAILS
      academicDetails:
        data.academicDetails ||
        "",

      // FIELD OF INTEREST
      fieldOfInterest:
        data.fieldOfInterest ||
        data.fieldOfInterestDetails ||
        "",

      // LANGUAGES
      languagesKnown:
        data.languagesKnown ||
        data.languages ||
        "",

      // STRENGTHS
      strengths:
        data.strengths ||
        data.strength ||
        "",

      // PERSONAL DETAILS
      fatherName:
        data.fatherName ||
        "",

      dob:
        data.dob ||
        "",

      gender:
        data.gender ||
        "",

      maritalStatus:
        data.maritalStatus ||
        "",

      nationality:
        data.nationality ||
        "",

      // DECLARATION
      declaration:
        data.declaration ||
        "",

      place:
        data.place ||
        "",

      date:
        data.date ||
        ""
    }
  }
];

const data = $('Validate Form').first().json;

// Skills
const skills = String(data.skills || '')
  .split(',')
  .map(s => s.trim())
  .filter(Boolean)
  .map(s => `• ${s}`)
  .join('\n');

// Strengths
const strengths = String(data.strengths || '')
  .split(',')
  .map(s => s.trim())
  .filter(Boolean)
  .map(s => `• ${s}`)
  .join('\n');

// Field of Interest
const interests = String(data.fieldOfInterest || '')
  .split(',')
  .map(s => s.trim())
  .filter(Boolean)
  .map(s => `• ${s}`)
  .join('\n');

// Certifications
const certifications = String(data.certifications || '')
  .split('\n')
  .map(s => s.trim())
  .filter(Boolean)
  .map(s => `• ${s}`)
  .join('\n');

// Projects
const projects = String(data.projects || '')
  .split('\n')
  .map(s => s.trim())
  .filter(Boolean)
  .map(s => `• ${s}`)
  .join('\n');

// Academic Details
const academicDetails = String(data.academicDetails || '')
  .split('\n')
  .map(s => s.trim())
  .filter(Boolean)
  .join('\n');

return [
  {
    json: {
      ...data,

      formattedSkills: skills,
      formattedStrengths: strengths,
      formattedInterests: interests,
      formattedCertifications: certifications,
      formattedProjects: projects,
      formattedAcademicDetails: academicDetails
    }
  }
];

const docId = $('Copy file').first().json.id;

const resumeUrl =
  'https://docs.google.com/document/d/' + docId + '/edit';

return [
  {
    json: {
      ...$json,
      resumeUrl: resumeUrl
    }
  }
];
